    //      1) a single-qubit unitary U.
    //      2) a positive integer power.
    // Output:
    //      A single-qubit unitary equal to U raised to the given power.
    function UnitaryPower (U : (Qubit => Unit is Adj + Ctl), power : Int) : (Qubit => Unit is Adj + Ctl) {
